// /sitemap.xml is generated by the Supabase `sitemap` edge function, but Supabase's
// gateway rewrites its Content-Type to text/plain. Vercel proxies it through
// api/sitemap.ts so crawlers receive application/xml.
//
// It also drops pages that are served `noindex` (the login page): a sitemap must only list
// URLs we want indexed, and Search Console flags "submitted URL marked noindex" otherwise.
//
// NOTE: relative imports only - Vercel's bundler does not resolve "@/".
import { NOINDEX_STATIC_PATHS } from "./staticPages";
import { DIRECTORY_HIDDEN } from "../siteSwitches";

/** Removes the directory hubs (/doctors, /doctors/...) while the directory is switched off. */
export function dropDirectoryHubs(xml: string): string {
  return xml.replace(/<url>[\s\S]*?<\/url>\s*/g, (entry) => {
    const loc = /<loc>([^<]*)<\/loc>/.exec(entry)?.[1] ?? "";
    try {
      const path = new URL(loc.replace(/&amp;/g, "&")).pathname;
      return path === "/doctors" || path.startsWith("/doctors/") ? "" : entry;
    } catch {
      return entry;
    }
  });
}

/** Removes <url> entries whose <loc> is one of the given paths on any host. */
export function dropPaths(xml: string, paths: readonly string[]): string {
  if (paths.length === 0) return xml;
  return xml.replace(/<url>[\s\S]*?<\/url>\s*/g, (entry) => {
    const loc = /<loc>([^<]*)<\/loc>/.exec(entry)?.[1] ?? "";
    let path = "";
    try {
      path = new URL(loc.replace(/&amp;/g, "&")).pathname;
    } catch {
      return entry;
    }
    return paths.includes(path) ? "" : entry;
  });
}

export async function proxySitemap(
  req: Request,
  supabaseUrl: string | undefined,
  f: typeof fetch = fetch,
): Promise<Response> {
  if (!supabaseUrl) return new Response("sitemap unavailable", { status: 503, headers: { "Cache-Control": "no-store" } });

  const part = new URL(req.url).searchParams.get("part");
  const target = `${supabaseUrl.replace(/\/$/, "")}/functions/v1/sitemap${part ? `?part=${encodeURIComponent(part)}` : ""}`;

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 15000);
  try {
    const upstream = await f(target, { signal: ctrl.signal });
    const body = await upstream.text();
    if (!upstream.ok || !body.startsWith("<?xml")) {
      return new Response("sitemap unavailable", { status: 502, headers: { "Cache-Control": "no-store" } });
    }
    const cleaned = dropPaths(body, NOINDEX_STATIC_PATHS);
    return new Response(DIRECTORY_HIDDEN ? dropDirectoryHubs(cleaned) : cleaned, {
      status: 200,
      headers: {
        "Content-Type": "application/xml; charset=utf-8",
        "Cache-Control": "public, max-age=0, s-maxage=3600, stale-while-revalidate=86400",
      },
    });
  } catch {
    return new Response("sitemap unavailable", { status: 502, headers: { "Cache-Control": "no-store" } });
  } finally {
    clearTimeout(timer);
  }
}
